<script>
(()=>{const filter=(input,selector)=>{const q=input.value.toLowerCase().trim();let visible=0;document.querySelectorAll(selector).forEach(row=>{const show=!q||row.dataset.search.includes(q);row.hidden=!show;if(show)visible++});return visible};const copy=document.querySelector('#content-search'),count=document.querySelector('#copy-count');if(copy){const update=()=>{const n=filter(copy,'.appearance-copy-row');count.textContent=n+' wording field'+(n===1?'':'s')+' shown.'};copy.addEventListener('input',update);update()}const palette=document.querySelector('#palette-search');if(palette)palette.addEventListener('input',()=>filter(palette,'.palette-item'));document.querySelectorAll('[data-color-picker]').forEach(picker=>picker.addEventListener('input',()=>{const field=picker.previousElementSibling;field.value=picker.value.toUpperCase()}));document.querySelectorAll('input[type=color][name]').forEach(picker=>picker.addEventListener('input',()=>picker.nextElementSibling.textContent=picker.value.toUpperCase()))})();
</script>
